/**
 * DataPipe end-to-end smoke test.
 *
 * Goal. Verify in under 60 s that a real participant session would land in
 * OSF: the build's runtime config posts a tiny burst of trial rows through
 * the production DataPipe endpoint, DataPipe writes one JSON file per chunk
 * into the configured OSF component, and the operator can open OSF and see
 * the file appear.
 *
 * What this page does, in order:
 *   1. Initialises a session with synthetic Prolific params
 *      (`prolific_pid = SMOKE_TEST_<timestamp>`, `study_id = smoke_test`)
 *      and `is_preview = true`. Analysis scripts already drop preview rows,
 *      so smoke data cannot contaminate the main batch even if it co-mingles
 *      in OSF.
 *   2. Writes five fake trial rows tagged `phase: 'smoke_test'` to IndexedDB
 *      via the same `appendTrialRow` path the production runner uses.
 *   3. Runs the production `uploadProgressNode` — same retry/backoff logic,
 *      same DataPipe envelope, same chunking. The participant-facing progress
 *      bar appears verbatim, then either "✓ Saved (5 rows in 1 chunks)" on
 *      success or the download-fallback message on failure.
 *   4. Runs the production `completionRedirectNode`. With the current
 *      placeholder Prolific completion URL it will show the test-build
 *      notice (intended) instead of redirecting.
 *
 * What to check afterwards:
 *   - DataPipe dashboard for experiment `YdaKHF3W2XX7` shows one new file.
 *   - OSF component `osf.io/rj4vz/` → `uwf5r` has a new JSON file named
 *     `SMOKE_TEST_<timestamp>__seq-1-5.json`.
 *   - The file's contents include the five fake rows + the
 *     `upload_session_end` summary row.
 *
 * To clean up after the test: log into OSF and delete the smoke files (or
 * leave them — the analyst pipeline filters `is_preview: true` rows
 * automatically).
 *
 * This page is intentionally separate from the production `index.html` entry
 * so it can never be hit by a real participant — Vite emits it as a sibling
 * file under `dist/smoke-test.html` when `npm run build` runs.
 */
import { initJsPsych } from 'jspsych';
import htmlKeyboardResponse from '@jspsych/plugin-html-keyboard-response';

import { initSession } from './prolific.js';
import { initStorage, appendTrialRow } from './storage.js';
import { uploadProgressNode, completionRedirectNode } from './conditions/debrief.js';
import { config } from './config.js';

const TIMESTAMP = new Date().toISOString().replace(/[:.]/g, '-');
const SMOKE_PID = `SMOKE_TEST_${TIMESTAMP}`;
const FAKE_ROW_COUNT = 5;

async function main() {
  await initStorage();

  const session = initSession(
    {
      prolific_pid: SMOKE_PID,
      study_id: 'smoke_test',
      session_id: SMOKE_PID,
      is_preview: true,
    },
    { is_pilot_run: false, pilot_label: 'smoke_test', source: 'smoke-test' }
  );

  const jsPsych = initJsPsych({
    on_data_update: (datum) => {
      appendTrialRow(datum).catch((err) => console.error('[smoke-test] storage write failed', err));
    },
  });
  window.jsPsych = jsPsych;

  const splash = {
    type: htmlKeyboardResponse,
    stimulus: `
      <div style="max-width: 38rem; margin: 0 auto; text-align: left;">
        <h2 style="text-align: center;">DataPipe smoke test</h2>
        <p>This page verifies the production data-egress path end-to-end. It will:</p>
        <ol>
          <li>Write ${FAKE_ROW_COUNT} fake trial rows to IndexedDB
              (<code>phase: 'smoke_test'</code>, <code>is_preview: true</code>).</li>
          <li>POST them through the configured uploader
              (<code>${config.uploader.provider}</code> →
              <code>${config.uploader.endpoint}</code>).</li>
          <li>DataPipe writes one JSON file per chunk into your OSF component.</li>
          <li>Show you the result, then quit.</li>
        </ol>
        <p>Runtime config in use:</p>
        <ul style="font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.9em;">
          <li>endpoint = <code>${config.uploader.endpoint ?? '(none)'}</code></li>
          <li>provider = <code>${config.uploader.provider ?? '(none)'}</code></li>
          <li>datapipe_experiment_id =
              <code>${config.uploader.datapipe_experiment_id ?? '(none)'}</code></li>
          <li>build_id = <code>${config.build_id}</code></li>
          <li>schema_version = <code>${config.schema_version}</code></li>
        </ul>
        <p>Session marker:</p>
        <ul style="font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.9em;">
          <li>prolific_pid = <code>${SMOKE_PID}</code></li>
          <li>is_preview = <code>true</code></li>
        </ul>
        <p style="text-align: center; margin-top: 1.5rem;">
          Press <kbd>Space</kbd> to run the test.
        </p>
      </div>
    `,
    choices: [' '],
    data: { phase: 'smoke_test_splash' },
  };

  const fakeTrials = Array.from({ length: FAKE_ROW_COUNT }, (_, i) => ({
    type: htmlKeyboardResponse,
    stimulus: `<div style="font-size: 1.5rem;">Generating fake trial ${i + 1} / ${FAKE_ROW_COUNT}…</div>`,
    trial_duration: 150,
    choices: 'NO_KEYS',
    data: {
      phase: 'smoke_test',
      smoke_trial_index: i,
      smoke_random_payload: Math.random().toString(36).slice(2),
    },
  }));

  jsPsych.run([splash, ...fakeTrials, uploadProgressNode({ session }), completionRedirectNode()]);
}

main().catch((err) => {
  console.error('[smoke-test] fatal init error', err);
  document.body.innerHTML = `
    <div style="max-width: 38rem; margin: 4rem auto; padding: 1.5rem; background: #2a0b0b; border-radius: 0.5rem;">
      <h2 style="margin: 0 0 1rem 0;">Smoke test failed to start</h2>
      <pre style="white-space: pre-wrap; font-size: 0.85rem;">${String(err?.stack ?? err)}</pre>
    </div>
  `;
});
